<?php namespace Workspace; $owner=$user['role']==='owner'; $names=array_column($members,'name','id'); ?>
<p class="lede">Организация: <?= h($user['organization_name']) ?>. Членство в команде не предоставляет доступ к закрытым проектам.</p>
<section class="panel"><div class="panelhead"><h2>Участники организации</h2><span class="count"><?= count($members) ?></span></div><div class="tablewrap"><table><thead><tr><th>Участник</th><th>Роль</th><th>Доступ</th><?php if ($owner): ?><th>Действие</th><?php endif ?></tr></thead><tbody>
<?php foreach ($members as $m): ?><tr><td><b><?= h($m['name']) ?></b><small><?= h($m['email']) ?></small></td><td><?= h(ROLES[$m['role']]) ?></td><td><span class="pill <?= $m['enabled']?'done':'' ?>"><?= $m['enabled']?'Активен':'Отключён' ?></span></td><?php if ($owner): ?><td><?php if ((int)$m['id']!==(int)$user['id']): ?><form method="post" class="inline"><?php formFields('org.role') ?><input type="hidden" name="member_id" value="<?= h($m['id']) ?>"><label>Роль<select name="role"><?php selectOptions(ROLES,$m['role']) ?></select></label><button class="secondary compact">Сохранить</button></form><form method="post"><?php formFields('org.remove') ?><input type="hidden" name="member_id" value="<?= h($m['id']) ?>"><button class="secondary compact">Исключить из организации</button></form><?php endif ?></td><?php endif ?></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel"><div class="panelhead"><h2>Команды</h2></div>
<?php foreach ($teams as $t): $ids=array_map('intval',array_column(array_filter($teamMembers,fn($m)=>(int)$m['team_id']===(int)$t['id']),'user_id')); ?>
<div class="inset"><h3><?= h($t['name']) ?></h3><?php if ($owner): ?><details><summary>Управление командой</summary><form method="post" class="inline"><?php formFields('team.rename') ?><input type="hidden" name="team_id" value="<?= h($t['id']) ?>"><label>Название<input name="name" value="<?= h($t['name']) ?>" maxlength="100" required></label><button class="secondary">Переименовать</button></form><form method="post"><?php formFields('team.delete') ?><input type="hidden" name="team_id" value="<?= h($t['id']) ?>"><button class="secondary compact">Удалить команду (проекты останутся)</button></form></details><?php endif ?><?php foreach ($ids as $id): ?><div class="splitrow"><span><?= h($names[$id]) ?></span><?php if ($owner): ?><form method="post"><?php formFields('team.remove') ?><input type="hidden" name="team_id" value="<?= h($t['id']) ?>"><input type="hidden" name="member_id" value="<?= $id ?>"><button class="secondary compact">Исключить</button></form><?php endif ?></div><?php endforeach ?>
<?php if ($owner && ($available=array_diff_key($names,array_flip($ids)))): ?><form method="post" class="inline"><?php formFields('team.add') ?><input type="hidden" name="team_id" value="<?= h($t['id']) ?>"><label>Участник<select name="member_id"><?php selectOptions($available) ?></select></label><button class="secondary">Добавить</button></form><?php endif ?></div><?php endforeach ?>
<?php if (!$teams): ?><p class="empty">Команд пока нет.</p><?php endif ?>
<?php if ($owner): ?><form method="post" class="inline inset"><?php formFields('team.create') ?><label>Название команды<input name="name" maxlength="100" required></label><button class="primary">Создать команду</button></form><?php endif ?></section>
<?php if ($owner): ?><section class="panel"><div class="panelhead"><h2>Приглашения</h2></div><div class="inset">
<?php if ($inviteToken): ?><p role="status">Передайте код лично приглашённому участнику. Код отображается один раз.</p><input aria-label="Одноразовый код" readonly value="<?= h($inviteToken) ?>"><p>Страница принятия: <a href="<?= h(url('invite')) ?>">Принять приглашение</a></p><?php endif ?>
<p>Роль владельца предоставляет полный доступ ко всем проектам этой организации.</p><form method="post" class="formgrid"><?php formFields('invite.issue') ?><label>Email<input name="email" type="email" required maxlength="254"></label><label>Роль<select name="role"><?php selectOptions(ROLES,'viewer') ?></select></label><label>Срок (часов)<input type="number" name="hours" min="1" max="168" value="24" required></label><div class="formend"><button class="primary">Создать приглашение</button></div></form></div>
<div class="tablewrap"><table><thead><tr><th>Email</th><th>Роль</th><th>Истекает (UTC)</th><th>Состояние</th></tr></thead><tbody><?php foreach ($invitations as $i): $active=!$i['accepted_at']&&!$i['revoked_at']&&(int)$i['expires_at']>time(); ?><tr><td><?= h($i['email']) ?></td><td><?= h(ROLES[$i['role']]) ?></td><td><?= h(gmdate('Y-m-d H:i',(int)$i['expires_at'])) ?></td><td><?= $i['accepted_at']?'Принято':($i['revoked_at']?'Отозвано':($active?'Активно':'Истекло')) ?><?php if ($active): ?><form method="post"><?php formFields('invite.revoke') ?><input type="hidden" name="invite_id" value="<?= h($i['id']) ?>"><button class="secondary compact">Отозвать</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
<section class="panel inset"><h2>Настройки организации</h2><form method="post" class="inline"><?php formFields('org.rename') ?><label>Название текущей организации<input name="name" maxlength="120" value="<?= h($user['organization_name']) ?>" required></label><button class="secondary">Переименовать</button></form><h2>Новая организация</h2><form method="post" class="inline"><?php formFields('org.create') ?><label>Название<input name="name" maxlength="120" required></label><button class="primary">Создать и переключиться</button></form></section><?php endif ?>
